// Detects explicit requests to create a log draft. The actual record is still
// generated by the server-side extraction model and reviewed by the owner.
(function exposeLogCommand(root) {
  function isRequest(value) {
    const text = String(value || "").trim().toLowerCase().slice(0, 600);
    if (!text) return false;

    const asksHow = /^(?:怎么|如何|怎样|为什么|what\b|how\b|why\b)/i.test(text);
    if (asksHow) return false;

    const chineseRequest = /(?:帮我|请|麻烦|把|将|给我).{0,40}(?:记(?:录|下来)?|写|生成|创建|整理|添加|加入).{0,16}(?:日志|记录|log)/i;
    const chineseImperative = /(?:记到|加入|添加到).{0,10}(?:日志|记录)|(?:生成|创建|写一?条|整理).{0,10}(?:日志|log)/i;
    const chineseShorthand = /(?:帮我|请|麻烦|把).{0,40}(?:记录一下|记一下|记下来)(?:吧|。|！|!|\s)*$/i;
    const englishRequest = /\b(?:please|can you|could you|would you|help me|i want you to)\b.{0,60}\b(?:log|record|create|generate|write|add)\b.{0,30}\b(?:log|entry|this|that|it)\b/i;
    const englishImperative = /\b(?:log|record)\s+(?:this|that|it)\b|\b(?:create|generate|write|add)\b.{0,24}\b(?:log|entry)\b/i;
    return chineseRequest.test(text) || chineseImperative.test(text) || chineseShorthand.test(text) ||
      englishRequest.test(text) || englishImperative.test(text);
  }

  root.LogCommand = Object.freeze({ isRequest });
})(globalThis);
